"""Audit pytest JUnit skips so Windows runs cannot silently lose coverage."""

from __future__ import annotations

import argparse
import os
import sys
from collections.abc import Sequence
from pathlib import Path

# The JUnit report is generated by local pytest, not untrusted input.
from xml.etree import ElementTree  # nosec B405

POSIX_ONLY_PREFIX = "posix_only:"
OUTPUT_TEST_FILE = "tests/test_output.py"
REQUIRED_WINDOWS_OUTPUT_CASES = (
    "test_windows_rejects_junction_output_parent",
    "test_windows_staged_output_pins_parent_directory",
    "test_windows_no_overwrite_preserves_existing_file",
    "test_windows_writer_failure_preserves_existing_file[conversion]",
    "test_windows_writer_failure_preserves_existing_file[template]",
    "test_windows_validation_failure_preserves_existing_file",
    "test_windows_rejects_real_casefolded_input_output_alias",
)


def _test_file(case: ElementTree.Element) -> str:
    """Recover the test module from pytest's optional file or classname fields."""
    file_name = case.get("file")
    if file_name:
        return file_name.replace("\\", "/")

    classname = case.get("classname", "").replace("\\", "/")
    parts = classname.split(".")
    for index, part in enumerate(parts):
        if part == "test_output":
            return "/".join(parts[: index + 1]) + ".py"
        if part.startswith("test_"):
            return "/".join(parts[: index + 1]) + ".py"
    return classname + ".py"


def _skip_reason(skipped: ElementTree.Element) -> str:
    message = (skipped.get("message") or "").strip()
    if message.startswith("Skipped:"):
        message = message.removeprefix("Skipped:").strip()
    if message:
        return message
    return "".join(skipped.itertext()).strip() or "<no reason>"


def find_unexpected_skips(junit_xml: Path, *, windows: bool) -> list[str]:
    """Enforce Windows skips and require every exact output safety case name."""
    # pytest generates this local report; it is not external or user-supplied XML.
    root = ElementTree.parse(junit_xml).getroot()  # nosec B314
    if not windows:
        return []

    required = set(REQUIRED_WINDOWS_OUTPUT_CASES)
    seen_required = set()
    violations = []
    for case in root.iter("testcase"):
        test_file = _test_file(case)
        test_name = case.get("name", "<unnamed>")
        is_output_test = test_file == OUTPUT_TEST_FILE
        is_required = is_output_test and test_name in required
        skipped_cases = case.findall("skipped")
        if is_required:
            seen_required.add(test_name)
        for skipped in skipped_cases:
            reason = _skip_reason(skipped)
            identity = f"{test_file}::{test_name}"
            if is_required:
                violations.append(
                    f"{identity}: required Windows output case was skipped: {reason}"
                )
            elif not reason.startswith(POSIX_ONLY_PREFIX):
                if is_output_test:
                    violations.append(
                        f"{identity}: skip reason must start with {POSIX_ONLY_PREFIX!r}; "
                        f"got {reason!r}"
                    )
                else:
                    violations.append(
                        f"{identity}: unexpected skip outside {OUTPUT_TEST_FILE}: {reason}"
                    )

    for name in REQUIRED_WINDOWS_OUTPUT_CASES:
        if name not in seen_required:
            violations.append(
                f"{OUTPUT_TEST_FILE}::{name}: missing required Windows output case"
            )
    return violations


def main(argv: Sequence[str] | None = None, *, windows: bool | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("junit_xml", type=Path, help="pytest --junitxml report")
    args = parser.parse_args(argv)
    if windows is None:
        windows = os.name == "nt"

    try:
        violations = find_unexpected_skips(args.junit_xml, windows=windows)
    except (OSError, ElementTree.ParseError) as error:
        print(f"Unable to audit pytest JUnit report: {error}", file=sys.stderr)
        return 2

    if violations:
        print("Windows test coverage audit failed:", file=sys.stderr)
        for violation in violations:
            print(f"  {violation}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
